package com.vocal.repository; import com.vocal.entity.Product; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.*; import java.math.BigDecimal; import java.util.Optional;
public interface ProductRepository extends JpaRepository<Product,Long>{ Optional<Product> findBySlug(String slug); @Query("select p from Product p where p.active=true and (:q is null or lower(p.name) like lower(concat('%',:q,'%'))) and (:category is null or p.category.slug=:category) and (:min is null or p.price>=:min) and (:max is null or p.price<=:max)") Page<Product> search(@Param("q") String q,@Param("category") String category,@Param("min") BigDecimal min,@Param("max") BigDecimal max, Pageable pageable); }
